<template>
  <sf-page-layout class="v3-weekly" title="Weekly Report" :glass="false" :asset="asset" :extended="true" :status-asset="asset('imgRightSide')" @back="$emit('action','back')" data-design-node="7697:14248">
    <template #back-icon><img :src="asset('imgGroup257')" alt="" style="transform:scaleX(-1)" data-source-asset="true"/></template>
    <template #trailing><button class="sf-icon-button" aria-label="Weekly report actions" @click="menu=true"><img :src="asset('img')" alt="" data-source-asset="true"/></button></template>
    <sf-feedback v-if="!report||!report.available" tone="empty" title="Your next weekly report" description="Complete at least two workouts in a week to see your full report here."/>
    <template v-else>
      <div class="weekly-greeting"><img :src="asset('imgEllipse1014')" width="56" height="56" alt=""><h2>Hi, {{ user.name }}</h2></div>
      <sf-card class="weekly-intro"><p>You logged {{ report.stats.time }} mins of exercise {{ period }}.<br>Here’s your weekly report:</p><img :src="asset('imgTrophyIcon')" width="126" height="126" alt=""/></sf-card>
      <sf-card class="weekly-card" title="Your Week">
        <template #accessory><button class="weekly-link" :aria-expanded="details?'true':'false'" @click="details=!details">Detail <img :src="asset('img1')" alt="" data-source-asset="true"/></button></template>
        <svg class="weekly-line-chart" viewBox="0 0 310 104" role="img" :aria-label="'Daily exercise minutes: '+report.daily.map(day=>day.day+' '+day.minutes).join(', ')">
          <defs><linearGradient id="weekly-area" x1="0" x2="0" y1="0" y2="1"><stop stop-color="#f9a08e" stop-opacity=".55"/><stop offset="1" stop-color="#f9a08e" stop-opacity="0"/></linearGradient></defs>
          <path :d="area" fill="url(#weekly-area)"/><path :d="line" stroke="#e81d1d" stroke-width="1.5" fill="none"/>
          <g v-for="(point,index) in points" :key="index"><circle :cx="point.x" :cy="point.y" r="3" fill="#f9a08e" stroke="white"/><text v-if="index===peak" :x="point.x" :y="point.y-10" text-anchor="middle" class="weekly-chart-value">{{ report.daily[index].minutes }} min</text><text :x="point.x" y="91" text-anchor="middle">{{ report.daily[index].day }}</text><text :x="point.x" y="102" text-anchor="middle">{{ report.daily[index].date.slice(-2) }}</text></g>
        </svg>
