<script>
import {SfPageLayout,SfCard,SfButton,SfBadge,SfFeedback,SfIcon,SfToast,SfSheet} from '@/design-system'
import {shareWeeklyReport} from './share-weekly-report'
export default {components:{SfPageLayout,SfCard,SfButton,SfBadge,SfFeedback,SfIcon,SfToast,SfSheet},props:{report:Object,user:Object,busy:Boolean},data(){return{menu:false,details:false,sharing:false,feedback:'',stats:[{key:'workouts',label:'Workouts',icon:'imgFrame'},{key:'activeDays',label:'Active Days',icon:'imgGroup259'},{key:'time',label:'Time (min)',icon:'imgFrame1'},{key:'calories',label:'Calories (kcal)',icon:'imgIconSideHot'}]}},computed:{period(){return this.report.weekStart.slice(5).replace('-','/')+'–'+this.report.weekEnd.slice(5).replace('-','/')},goalLabel(){return {health_vitality:'Health & Vitality',weight_loss:'Weight Loss',build_muscle:'Build Muscle',rehab_stretch:'Rehab & Stretch'}[this.report.goal]||'Workout mix'},peak(){const values=this.report.daily.map(day=>day.minutes);return values.indexOf(Math.max(...values))},points(){const max=Math.max(1,...this.report.daily.map(day=>day.minutes));return this.report.daily.map((day,index)=>({x:14+index*47,y:72-day.minutes/max*46}))},line(){return this.points.map((point,index)=>(index?'L':'M')+point.x+' '+point.y).join(' ')},area(){return this.line+' L296 78 L14 78 Z'},radarAxes(){return [this.radarPoint(100,0),this.radarPoint(100,1),this.radarPoint(100,2)]}},methods:{asset(name){return '/assets/figma/commerce-mvp/weekly/'+name+(name==='imgEllipse1014'||name==='imgTrophyIcon'?'.png':'.svg')},number(value){return new Intl.NumberFormat('en-US',{maximumFractionDigits:1}).format(value)},mixLabel(type){return{cardio:'Cardio',strength:'Strength',mind_body:'Mind-Body'}[type]||type},shortDay(date){return new Intl.DateTimeFormat('en-US',{month:'short',day:'numeric',timeZone:'UTC'}).format(new Date(date+'T12:00:00Z'))},radarPoint(value,index){const vectors=[[-.866,.5],[.866,.5],[0,-1]];return{x:155+vectors[index][0]*value*.8,y:123+vectors[index][1]*value*.8}},radar(values){return values.map((value,index)=>{const point=this.radarPoint(value,index);return point.x+','+point.y}).join(' ')},async share(){if(this.sharing||!this.report?.available)return;this.sharing=true;try{this.feedback=await shareWeeklyReport(this.report)}catch(error){if(error.name!=='AbortError')this.feedback='Could not prepare your share card. Please try again.'}finally{this.sharing=false}}}}
</script>
